(lib.westren = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.nyala = function () {
			
			const werstanL = this.parent.werstanL.nilai;
			const werstanM = this.parent.werstanM.nilai;
			const werstanH = this.parent.werstanH.nilai;
			
		    // L
			if (werstanL == 12 || werstanL == 1 ) {
				
				if (werstanM == 12 || werstanM == 1 ) {
					this.parent.setNilaiAwal("werstanH", werstanM * 0.8);
					this.parent.hubungan("werstanM", 1);
					this.parent.hubungan("werstanL", 0);
				}
				else if (werstanH == 12 || werstanH == 1 ) {
					this.parent.setNilaiAwal("werstanH", werstanH*1.2);
					this.parent.hubungan("werstanH", 1);
					this.parent.hubungan("werstanL", 0);
				} else{
					this.parent.setNilaiAwal("werstanH",werstanL * 0.6);
					this.parent.hubungan("werstanL", 1);
				}
			} else if (werstanM == 0 || werstanL == 0 ) {
				this.parent.setNilaiAwal("werstanH",0);
				}
				
			
			
			if (werstanM == 12 || werstanM == 1 ) {
					this.parent.setNilaiAwal("werstanH", werstanM * 0.8);
					this.parent.hubungan("werstanM", 1);
				    this.parent.hubungan("werstanL", 0);
				} 
		
			
			
				
				
		};
		
				
		
		// Jalankan nyala setiap 1 detik
		this.timer = setInterval(() => this.nyala(), 1000);
		
		this.tutup_werstan.addEventListener("click", function() {
		    this.tutup_werstan.visible= false;
			
		}.bind(this));
		
		this.inti_werstan.addEventListener("click", function() {
		    this.tutup_werstan.visible= true;
		
		}.bind(this));
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.tutup_werstan = new lib.tutup_werstan();
	this.tutup_werstan.name = "tutup_werstan";
	this.tutup_werstan.setTransform(3.25,-6.8);

	this.inti_werstan = new lib.inti_werstan();
	this.inti_werstan.name = "inti_werstan";
	this.inti_werstan.setTransform(1.95,6.6,1,1,0,0,0,0,0.2);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.inti_werstan},{t:this.tutup_werstan}]}).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.westren, new cjs.Rectangle(-87.3,-49.1,181.2,101.30000000000001), null);


