		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.posisi =0;
		 
		this.alarm = false;
		
		this.saklar_diam = function() {
		    this.alarm = !this.alarm;
		    if (this.alarm) {
		        this.parent.setNilaiAwal("antenaAlarm", 1); // alarm diam
		    } else {
		        this.parent.setNilaiAwal("antenaAlarm", 0); // alarm menyala
		    }
		}.bind(this);
		
		this.panggil = false;
		this.saklar_panggil = function() {
		    this.panggil = !this.panggil ;
		    if (this.panggil) {
		        this.parent.hubungan("antenaAlarm", 1); // alarm diam
		    } else {
		        this.parent.hubungan("antenaAlarm", 0); // alarm menyala
		    }
		}.bind(this);
		
		
		 
