		this.posisi_acc= function() {
			this.selector.rotation=-50;
			
			this.nyala();
			this.tuas.y=-9;
				
			
			
		}
		
		this.posisi_off= function() {
			this.selector.rotation=0;
			
			this.nyala();
			this.tuas.y=-24;
			
				
			
		}
		
		this.posisi_on= function() {
			this.selector.rotation=60;
			
			this.nyala();
			this.tuas.y=7;
			
				
			
			
			//console.log(`Nilai kkb: ${this.kkb}`);
			//console.log(`Nilai kkig: ${this.kkig}`);
				
			
		}
		
		this.posisi_st= function() {
				this.selector.rotation=120;
				this.nyala();
				this.tuas.y=24;
				
			
			
		}
		// ST 120
		//ON 60
		//OFF 0
		//ACC -50
		this.nyala = function () {
		  // Ambil referensi ke objek dari parent
		  const kkb = this.parent.kkb;
		  const kkig = this.parent.kkig;
		  const selector = this.selector;
		
		  if (!kkb || !kkig || !selector) {
		    console.error("kkb, kkig, atau selector tidak ditemukan");
		    return;
		  }
		
		  // Cek rotasi selector
		  const angle = Math.round(selector.rotation);
		
		  if (angle === 60) {
			this.parent.hubungan("kkb", 1);
			  
			  
			this.parent.setNilaiAwal("kkst", 0);
		    this.parent.setNilaiAwal("kkig", kkb.nilai);
			this.parent.setNilaiAwal("kkacc", kkb.nilai);
		  }else if (angle === -50) {
			this.parent.hubungan("kkb", 1);
			
			this.parent.setNilaiAwal("kkig", 0);
			this.parent.setNilaiAwal("kkst", 0);
			this.parent.setNilaiAwal("kkacc", kkb.nilai);
		  }else if (angle === 120) {
			this.parent.hubungan("kkb", 1);
			
			this.parent.setNilaiAwal("kkacc", 0);
		    this.parent.setNilaiAwal("kkig", kkb.nilai);
			this.parent.setNilaiAwal("kkst", kkb.nilai);
		  }else {
			this.parent.hubungan("kkb", 0);
			  
		    this.parent.setNilaiAwal("kkig", 0);
			this.parent.setNilaiAwal("kkacc",0);
			this.parent.setNilaiAwal("kkst",0);
			
		  }
		
		  // Panggil fungsi dari parent/root
		  if (this.parent.updateSemuaTarget) this.parent.updateSemuaTarget();
		  if (this.parent.drawAllLines) this.parent.drawAllLines();
		};
		
		
		
		
		
		
		
		
