(lib.HeadLampLH = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.Jauh.visible = false;
		this.Dekat.visible = false;
		
		setInterval(() => {
		  this.nyala();
		}, 1000); // setiap 1 detik
		
		
		this.nyala = function() {
		    const nilai1 = this.parent.HLLH1.nilai;
		    const nilai2 = this.parent.HLLH2.nilai;
			const nilai3 = this.parent.HLLH3.nilai;
			
			this.parent.tahanan("HLLH1", 1);
		    this.parent.tahanan("HLLH2", 2500);
			  
		    // volt berdasarkan nilai terbesar
		    const volt12 = (Math.max(nilai1, nilai2) * Math.min(nilai1, nilai2)/12) ;
			const volt13 = (Math.max(nilai1, nilai3) * Math.min(nilai1, nilai3)/12) ;
			this.Dekat.scaleX = this.Dekat.scaleY = volt12;
			this.Jauh.scaleX = this.Jauh.scaleY = volt13;
			  
			  
		    if (nilai1 >nilai2 && nilai2 !=0 ) {
		      this.Dekat.visible = true;
			  this.Dekat.alpha = 0.7;
			 
			  this.parent.hubungan("HLLH2", 1);
		    } else  if (nilai2 > nilai1  && nilai1 !=0 ) {
		      this.Dekat.visible = true;
			  this.Dekat.alpha = 0.7;
			
			  this.parent.hubungan("HLLH1", 1);
		    }else {
		      this.Dekat.visible = false;
			  this.parent.hubungan("HLLH1", 0);
			  this.parent.hubungan("HLLH2", 0);
		    }
		
			if (nilai1 >nilai3 && nilai3 !=0 ) {
		      this.Jauh.visible = true;
			  this.Jauh.alpha = 0.8;
			  
			  this.parent.hubungan("HLLH3", 1);
		    } else  if (nilai3 > nilai1  && nilai1 !=0 ) {
		      this.Jauh.visible = true;
			  this.Jauh.alpha = 0.8;
				
			  this.parent.hubungan("HLLH1", 1);
		    }else {
		      this.Jauh.visible = false;
			  this.parent.hubungan("HLLH1", 0);
			  this.parent.hubungan("HLLH3", 0);
		    }
		};
		
		
		this.wiring.addEventListener("click", buka_tutup.bind(this));
		var aktif = true;
		function buka_tutup() {
		    // Toggle status aktif
		    aktif = !aktif;
		
		    // Jika aktif bernilai true, set rotasi point ke 0, jika false, set ke -45
		    if (aktif) {
		        this.komponen.visible= true;
		    } else {
		        this.komponen.visible= false;
				this.Dekat.visible= false;
		    }
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.Jauh = new lib.Jauh();
	this.Jauh.name = "Jauh";
	this.Jauh.setTransform(-0.85,-14.8,1.1798,1.1801,0,0,0,-0.4,-0.5);

	this.Dekat = new lib.dekat();
	this.Dekat.name = "Dekat";
	this.Dekat.setTransform(-0.85,-6.05,1.1798,1.1801,0,0,0,-0.4,-0.1);

	this.komponen = new lib.komponenHD();
	this.komponen.name = "komponen";
	this.komponen.setTransform(0,-4.1);

	this.wiring = new lib.wiring_lampuHD();
	this.wiring.name = "wiring";
	this.wiring.setTransform(-4.2,20.6,1.962,1.962);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.wiring},{t:this.komponen},{t:this.Dekat},{t:this.Jauh}]}).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.HeadLampLH, new cjs.Rectangle(-145.9,-158.1,294.8,303.2), null);


