		function setupButtonClicks() {
			Button.forEach(btn => {
				if (!btn.terminal) return;
		
				btn.terminal.cursor = "pointer";
				btn.terminal.on("click", () => {
					if (!selectedBtnStart) {
						selectedBtnStart = btn;
						console.log("Memulai koneksi dari:", btn.nama);
					} else {
						const namaStart = selectedBtnStart.nama;
						const namaTarget = btn.nama;
		
						const nilaiAwalStart = selectedBtnStart.nilaiAwal ?? 0;
						const nilaiAwalTarget = btn.nilaiAwal ?? 0;
		
						const index = koneksi.findIndex(k =>
							(k.startNama === namaStart && k.targetNama === namaTarget) ||
							(k.startNama === namaTarget && k.targetNama === namaStart)
						);
		
						if (index !== -1) {
							koneksi.splice(index, 1);
							console.log(`🗑️ Koneksi dihapus: ${namaStart} ↔ ${namaTarget}`);
						} else {
							if (namaStart === namaTarget) {
								selectedBtnStart = null;
								return;
							}
		
							const pasanganDilarang = 
								(nilaiAwalStart === 1 && nilaiAwalTarget === 12) ||
								(nilaiAwalStart === 12 && nilaiAwalTarget === 1);
		
							if (pasanganDilarang) {
								selectedBtnStart = null;
								return;
							}
		
							if (nilaiAwalStart === 1 || nilaiAwalTarget === 12) {
								selectedBtnStart = null;
								return;
							}
		
							koneksi.push({
								startNama: namaStart,
								targetNama: namaTarget
							});
						}
		
						updateSemuaTarget();
						drawAllLines();
						selectedBtnStart = null;
					}
				});
			});
		}
		
		function drawAllLines() {
			garisKoneksi.graphics.clear();
		
			koneksi.forEach(k => {
				const startBtn = Button.find(b => b.nama === k.startNama);
				const targetBtn = Button.find(b => b.nama === k.targetNama);
		
				if (startBtn && targetBtn && startBtn.terminal && targetBtn.terminal) {
					const globalStart = startBtn.terminal.localToGlobal(0, 0);
					const globalEnd = targetBtn.terminal.localToGlobal(0, 0);
					const localStart = self.globalToLocal(globalStart.x, globalStart.y);
					const localEnd = self.globalToLocal(globalEnd.x, globalEnd.y);
		
					const controlX = (localStart.x + localEnd.x) / 2;
					const dx = localEnd.x - localStart.x;
					const dy = localEnd.y - localStart.y;
					const distance = Math.sqrt(dx * dx + dy * dy);
					const bendFactor = 0.3;
					const controlY = Math.max(localStart.y, localEnd.y) + distance * bendFactor;
					const warnaGaris = startBtn.color || "#00AAFF";
		
					const g = garisKoneksi.graphics;
					g.setStrokeStyle(3)
					.beginStroke(warnaGaris)
					.moveTo(localStart.x, localStart.y)
					.quadraticCurveTo(controlX, controlY, localEnd.x, localEnd.y)
					.endStroke();
		
					const t = 0.95;
					const dxArrow = (1 - t) * (controlX - localStart.x) + t * (localEnd.x - controlX);
					const dyArrow = (1 - t) * (controlY - localStart.y) + t * (localEnd.y - controlY);
					const angle = Math.atan2(dyArrow, dxArrow);
		
					const arrowLength = 10;
					const arrowAngle = Math.PI / 6;
		
					const x1 = localEnd.x - arrowLength * Math.cos(angle - arrowAngle);
					const y1 = localEnd.y - arrowLength * Math.sin(angle - arrowAngle);
					const x2 = localEnd.x - arrowLength * Math.cos(angle + arrowAngle);
					const y2 = localEnd.y - arrowLength * Math.sin(angle + arrowAngle);
		
					g.setStrokeStyle(3)
					.beginStroke(warnaGaris)
					.moveTo(localEnd.x, localEnd.y)
					.lineTo(x1, y1)
					.moveTo(localEnd.x, localEnd.y)
					.lineTo(x2, y2)
					.endStroke();
				}
			});
		
			stage.update();
		
			// REVISI: Paksa menu 'slide' kembali ke lapisan teratas setelah gambar garis
			if (self.slide && self.slide.parent) {
				self.slide.parent.setChildIndex(self.slide, self.slide.parent.numChildren - 1);
			}
		}
		
		function updateSemuaTarget() {
			Button.forEach(btn => {
				btn.nilai = 0;
				btn.hitung = 0;
			});
		
			Button.forEach(btn => {
				btn.nilai = btn.nilaiAwal;
			});
		
			let changed = true;
			let iterasi = 0;
			const maxIterasi = 20;
		
			while (changed && iterasi < maxIterasi) {
				changed = false;
				iterasi++;
		
				const nilaiBaru = {};
				Button.forEach(btn => {
					nilaiBaru[btn.nama] = { nilai: 0, hitung: 0 };
				});
		
				koneksi.forEach(k => {
					const start = Button.find(b => b.nama === k.startNama);
					const target = Button.find(b => b.nama === k.targetNama);
		
					if (start && target) {
						if (start.nilai >= 6) {
							nilaiBaru[target.nama].nilai += start.nilai;
							nilaiBaru[target.nama].hitung += 1;
						}
					}
				});
		
				koneksi.forEach(k => {
					const start = Button.find(b => b.nama === k.startNama);
					const target = Button.find(b => b.nama === k.targetNama);
		
					if (start && target) {
						if (target.nilai != 0 && target.nilai <= 1 && start.nilai != -1) {
							nilaiBaru[start.nama].nilai += target.nilai;
							nilaiBaru[start.nama].hitung += 1;
							if(start.hubungan != 0){
								target.hubungan = start.hubungan;
							}
						}
						if (start.nilai == -1) {
							nilaiBaru[target.nama].nilai += start.nilai + 2;
							nilaiBaru[target.nama].hitung += 1;
							target.hubungan = start.hubungan;			
						}
					}
				});
		
				Button.forEach(btn => {
					if (nilaiBaru[btn.nama].hitung > 0) {
						const rata = nilaiBaru[btn.nama].nilai / nilaiBaru[btn.nama].hitung;
						const rataBulatan = Math.round(rata * 10) / 10;
		
						if (btn.nilai !== rataBulatan) {
							btn.nilai = rataBulatan;
							changed = true;
						}
					} else {
						if (btn.nilai !== btn.nilaiAwal) {
							btn.nilai = btn.nilaiAwal;
							changed = true;
						}
					}
				});
			}
		
			Button.forEach(btn => {
				if (btn.terminal) {
					btn.terminal.nilai = btn.nilai;
					btn.terminal.hubungan = btn.hubungan;
					btn.terminal.terminalAwal = btn.terminalAwal;
				}
			});
		
			stage.update();
			updateAnimations();
			if(self.status_ulang == true){
				self.ulang();
			}
		}
		
